// HTTP requests built from kit/operations.json: validated arguments placed in path, query,
// headers and body, credentials from environment variables. Part of a skill generated by spec2skill;
// plain ESM for Node.js 20+, no dependencies.
import { ArgsError, HttpError, api, guard, validateArgs } from './args.mjs';

export { ArgsError, HttpError, validateArgs };

/** The first security alternative whose variables are all set, else the first one. */
function schemesFor(op, env) {
  const alternatives = (op.security.length ? op.security : [[]]).map((ids) => api.auth.filter((s) => ids.includes(s.id)));
  return alternatives.find((set) => set.every((s) => s.env.every((name) => env[name]))) ?? alternatives[0];
}

/**
 * `{ method, url, headers, body, missingAuth }` for one operation; throws ArgsError on bad arguments.
 * A missing credential is left as a `$NAME` placeholder and listed in `missingAuth`.
 * A name declared in two places (path and body, say) is sent in both.
 */
export function buildRequest(id, args = {}, { baseUrl, env = process.env } = {}) {
  const op = validateArgs(id, args);
  const base = (baseUrl ?? env[`${api.envPrefix}_BASE_URL`] ?? api.servers[0] ?? '').replace(/\/+$/, '');
  const path = op.path.replace(/\{([^}]+)\}/g, (_, name) => encodeURIComponent(String(args[name])));
  const query = new URLSearchParams();
  const headers = {};
  const cookies = [];
  const fields = {};
  for (const p of op.inputs) {
    const v = args[p.name];
    if (v === undefined || p.in === 'path') continue;
    if (p.in === 'query') for (const item of [v].flat()) query.append(p.name, String(item));
    else if (p.in === 'header') headers[p.name.toLowerCase()] = String(v);
    else if (p.in === 'cookie') cookies.push(`${p.name}=${encodeURIComponent(String(v))}`);
    else fields[p.name] = v;
  }
  const missingAuth = [];
  for (const s of schemesFor(op, env)) {
    const [a, b] = s.env.map((name) => env[name] || (missingAuth.push(name), `$${name}`));
    if (s.type === 'apiKey' && s.in === 'query') query.set(s.name, a);
    else if (s.type === 'apiKey' && s.in === 'cookie') cookies.push(`${s.name}=${a}`);
    else if (s.type === 'apiKey') headers[s.name.toLowerCase()] = a;
    else if (s.scheme === 'basic') headers.authorization = `Basic ${btoa(`${a}:${b}`)}`;
    else if (a) headers.authorization = `Bearer ${a}`;
  }
  if (cookies.length) headers.cookie = cookies.join('; ');
  let body;
  if (op.body && Object.keys(fields).length) {
    const value = op.body.whole ? fields.body : fields;
    if (op.body.type.includes('multipart')) {
      body = new FormData();
      for (const [k, v] of Object.entries(value)) body.append(k, v instanceof Blob ? v : String(v));
    } else {
      headers['content-type'] = op.body.type;
      body = op.body.type.includes('urlencoded')
        ? new URLSearchParams(Object.entries(value).map(([k, v]) => [k, String(v)])).toString()
        : typeof value === 'string' && !op.body.type.includes('json') ? value : JSON.stringify(value);
    }
  }
  const qs = query.toString();
  return { method: op.method.toUpperCase(), url: base + path + (qs ? `?${qs}` : ''), headers, body, missingAuth };
}

/**
 * Sends one call with `fetch` and returns the parsed JSON (or text) body. Refuses a destructive
 * call without `confirmed: true` and a call whose credentials are unset; throws HttpError on non-2xx.
 */
export async function request(id, args = {}, { confirmed, fetch = globalThis.fetch, ...options } = {}) {
  guard(id, confirmed);
  const { method, url, headers, body, missingAuth } = buildRequest(id, args, options);
  if (missingAuth.length) throw new ArgsError(`${id}: set ${missingAuth.join(' and ')} in the environment first`);
  const res = await fetch(url, { method, headers, body });
  const text = await res.text();
  let data = text;
  try {
    data = text ? JSON.parse(text) : undefined;
  } catch {} // not JSON: keep the text
  if (!res.ok) throw new HttpError(`${id}: ${method} ${url} answered ${res.status}`, res.status, data);
  return data;
}
